def verifier(assign):
    # Validate inputs
    if not isinstance(assign, dict):
        return (False, None)  # invalid input format
    if 'dimension' not in assign or 'iterations' not in assign:
        return (False, None)  # missing placeholders
    d = assign['dimension']
    k = assign['iterations']
    if not (isinstance(d, int) and isinstance(k, int)):
        return (False, None)
    if d < 4 or d > 20:  # keep within reasonable bounds
        return (False, None)
    if k < 3 or k > 50:
        return (False, None)
    # Compute r = d / 2^{d-1}
    r_num = d
    r_den = 2 ** (d - 1)
    if r_den - d <= 0:
        return (False, None)  # ensures geometric factor < 1
    # A = (d+1) / (2(2^{d-1} - d))
    A_num = d + 1
    A_den = 2 * (r_den - d)
    # r^k
    rk_num = r_num ** k
    rk_den = r_den ** k
    # (1 - r^k)
    B_num = rk_den - rk_num
    B_den = rk_den
    # A * (1 - r^k)
    AB_num = A_num * B_num
    AB_den = A_den * B_den
    g = gcd(AB_num, AB_den)
    AB_num //= g
    AB_den //= g
    # V = 1 + A*(1 - r^k) = 1 + AB_num/AB_den
    V_num = AB_den + AB_num
    V_den = AB_den
    g2 = gcd(V_num, V_den)
    V_num //= g2
    V_den //= g2
    # Enforce nontriviality to avoid guessing
    if V_den < 64:
        return (False, None)
    ans = V_num + V_den
    return (True, ans)


        def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
            """Return dict with assignment/question/answer or raise RuntimeError."""
            start = time.time()
            attempts = 0
            while time.time() - start < timeout_seconds:
                attempts += 1
                rng = _RNGShim(seed + attempts)
                assignment = generator(rng)
                valid, answer = verifier(assignment)
                if valid:
                    question = LANGUAGE_WRAPPER.format(**assignment)
                    return {
                        "assignment": assignment,
                        "question": question,
                        "answer": answer,
                        "attempts": attempts,
                        "elapsed_seconds": time.time() - start,
                    }
            raise RuntimeError("Failed to sample a valid assignment within timeout_seconds")
